export interface ShopCategory {
  id: string;
  slug: string;
  name: string;
  description: string;
  symbol: string;
}

export interface GoldSpecification {
  metal: string;
  gemstones: string;
  clasp?: string;
  packaging?: string;
  certificate?: string;
}

export interface ShopProduct {
  id: string;
  slug: string;
  name: string;
  categoryId: string;
  categoryName: string;
  theme?: "doble-perforacion" | "reiki" | "runas" | "geometria" | "angelical" | "altar" | "talismanes" | "duos" | "alta-joyeria-oro" | "ambar-chiapas";
  isDoublePerforation?: boolean;
  price: number;
  formattedPrice: string;
  shippingNote: string;
  tagline: string;
  description: string;
  ritualUse: string;
  details: string[];
  inStock: boolean;
  badge?: string;
  imageUrl: string;
  secondaryImageUrl?: string;
  images?: string[];
  stoneType?: string;
  beadSize?: string;
  featured?: boolean;
  duoPairId?: string;
  duoPairName?: string;
  duoPairPrice?: number;
  braceletPairId?: string;
  goldSpecifications?: GoldSpecification;
}

